previewCss:
.darma-loader-darma-b10-shooting-star { --accent: var(--loader-color, #fde047); --accent-2: var(--loader-secondary-color, #a855f7); width: var(--loader-size, 84px); height: var(--loader-size, 84px); position: relative; overflow: hidden; }
.darma-loader-darma-b10-shooting-star span { position: absolute; top: 12%; left: -18%; width: calc(var(--loader-size, 84px) * .1); height: calc(var(--loader-size, 84px) * .1); border-radius: 50%; background: radial-gradient(circle, #fff, var(--accent)); box-shadow: 0 0 calc(var(--loader-size, 84px) * .1) var(--accent); animation: darma-loader-darma-b10-shooting-star-shoot calc(var(--loader-speed, 1s) * 1.6) ease-in infinite; }
.darma-loader-darma-b10-shooting-star span::after { content: ''; position: absolute; right: 55%; top: 50%; width: calc(var(--loader-size, 84px) * .55); height: 2px; margin-top: -1px; background: linear-gradient(90deg, transparent, var(--accent-2)); }
@keyframes darma-loader-darma-b10-shooting-star-shoot { 0% { transform: translate(0, 0); opacity: 0; } 15% { opacity: 1; } 85% { opacity: 1; } 100% { transform: translate(calc(var(--loader-size, 84px) * 1.4), calc(var(--loader-size, 84px) * .72)); opacity: 0; } }

